import 'package:flutter/material.dart';

class MetricCard extends StatelessWidget { final String label, value, unit; final IconData icon; final Color accent; const MetricCard({super.key, required this.label, required this.value, required this.unit, required this.icon, required this.accent});
  @override Widget build(BuildContext context) { return Container(padding: const EdgeInsets.all(16), decoration: BoxDecoration(color: Theme.of(context).cardColor, borderRadius: BorderRadius.circular(20), border: Border.all(color: Theme.of(context).dividerColor.withValues(alpha: .5))), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Container(width: 34, height: 34, decoration: BoxDecoration(color: accent.withValues(alpha: .11), borderRadius: BorderRadius.circular(10)), child: Icon(icon, color: accent, size: 19)), const SizedBox(height: 13), Text(label, style: Theme.of(context).textTheme.labelMedium?.copyWith(color: Theme.of(context).colorScheme.onSurface.withValues(alpha: .6))), const SizedBox(height: 4), Row(crossAxisAlignment: CrossAxisAlignment.end, children: [Flexible(child: FittedBox(fit: BoxFit.scaleDown, alignment: Alignment.centerLeft, child: Text(value, style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.w800)))), const SizedBox(width: 4), Text(unit, style: Theme.of(context).textTheme.labelSmall?.copyWith(color: Theme.of(context).colorScheme.onSurface.withValues(alpha: .55)))] )])); }
